package counter

import "testing"

// This exercise is inverted: the deliverable is the test suite itself.
// makeCounter() (see maker.go) selects the implementation under test via
// the COUNTER_IMPL environment variable, e.g. `COUNTER_IMPL=4 go test`.
//
// The suite must PASS on Impl4 (the correct implementation) and FAIL on:
//   - Impl1: counts each '\n' as a line, undercounting strings that do not
//     end in a newline.
//   - Impl2: only treats ASCII A-Z / a-z as letters.
//   - Impl3: iterates byte-wise, breaking both Characters() and Letters()
//     for multi-byte UTF-8 input.

type testCase struct {
	name        string
	strings     []string
	wantLines   int
	wantLetters int
	wantChars   int
}

var testCases = []testCase{
	{
		name: "empty counter",
	},
	{
		name:        "single word without trailing newline",
		strings:     []string{"hello"},
		wantLines:   1,
		wantLetters: 5,
		wantChars:   5,
	},
	{
		name:        "single word with trailing newline",
		strings:     []string{"hello\n"},
		wantLines:   1,
		wantLetters: 5,
		wantChars:   6,
	},
	{
		name:        "two lines without trailing newline",
		strings:     []string{"hello\nworld"},
		wantLines:   2,
		wantLetters: 10,
		wantChars:   11,
	},
	{
		name:        "two lines with trailing newline",
		strings:     []string{"hello\nworld\n"},
		wantLines:   2,
		wantLetters: 10,
		wantChars:   12,
	},
	{
		name:        "punctuation and digits are not letters",
		strings:     []string{"Hello, World! 123"},
		wantLines:   1,
		wantLetters: 10,
		wantChars:   17,
	},
	{
		name:        "add calls accumulate within one line",
		strings:     []string{"foo", "bar"},
		wantLines:   1,
		wantLetters: 6,
		wantChars:   6,
	},
	{
		name:        "add calls accumulate across a line boundary",
		strings:     []string{"foo\n", "bar"},
		wantLines:   2,
		wantLetters: 6,
		wantChars:   7,
	},
	{
		name:        "add calls each ending in a newline",
		strings:     []string{"foo\n", "bar\n"},
		wantLines:   2,
		wantLetters: 6,
		wantChars:   8,
	},
	{
		name:        "non-ASCII letters are letters",
		strings:     []string{"äöü"},
		wantLines:   1,
		wantLetters: 3,
		wantChars:   3,
	},
	{
		name:        "CJK character is one letter and one character",
		strings:     []string{"中"},
		wantLines:   1,
		wantLetters: 1,
		wantChars:   1,
	},
	{
		name:        "non-ASCII letters across add calls",
		strings:     []string{"foo\n", "bär"},
		wantLines:   2,
		wantLetters: 6,
		wantChars:   8,
	},
	{
		name:        "non-ASCII letters without trailing newline",
		strings:     []string{"héllo", "wörld"},
		wantLines:   1,
		wantLetters: 10,
		wantChars:   10,
	},
}

func TestCounter(t *testing.T) {
	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			c := makeCounter()
			for _, s := range tc.strings {
				c.AddString(s)
			}
			if got := c.Lines(); got != tc.wantLines {
				t.Errorf("Lines() = %d, want %d", got, tc.wantLines)
			}
			if got := c.Letters(); got != tc.wantLetters {
				t.Errorf("Letters() = %d, want %d", got, tc.wantLetters)
			}
			if got := c.Characters(); got != tc.wantChars {
				t.Errorf("Characters() = %d, want %d", got, tc.wantChars)
			}
		})
	}
}

